
import React, { useState, useMemo } from 'react';
import { useLanguage } from '../context/LanguageContext';
import { elements, Element } from '../constants/elements';
import { Info, X, Search, BookOpen, ChevronRight } from 'lucide-react';

const PeriodicTable: React.FC = () => {
  const { t } = useLanguage();
  const [selected, setSelected] = useState<Element | null>(null);
  const [search, setSearch] = useState('');

  const categoryColors: Record<string, string> = {
    diatomic_nonmetal: "bg-green-100 text-green-800 border-green-200",
    noble_gas: "bg-purple-100 text-purple-800 border-purple-200",
    alkali_metal: "bg-red-100 text-red-800 border-red-200",
    alkaline_earth_metal: "bg-orange-100 text-orange-800 border-orange-200",
    metalloid: "bg-amber-100 text-amber-800 border-amber-200",
    polyatomic_nonmetal: "bg-emerald-100 text-emerald-800 border-emerald-200",
    post_transition_metal: "bg-blue-100 text-blue-800 border-blue-200",
    transition_metal: "bg-yellow-50 text-yellow-800 border-yellow-200",
    lanthanide: "bg-pink-100 text-pink-800 border-pink-200",
    actinide: "bg-rose-100 text-rose-800 border-rose-200",
    unknown: "bg-slate-100 text-slate-800 border-slate-200"
  };

  const filteredElements = useMemo(() => {
    return elements.filter(el => 
      el.name.toLowerCase().includes(search.toLowerCase()) || 
      el.symbol.toLowerCase().includes(search.toLowerCase()) ||
      el.number.toString() === search
    );
  }, [search]);

  return (
    <div className="max-w-[1400px] mx-auto px-4 py-12 space-y-16">
      <div className="text-center space-y-4">
        <h2 className="text-4xl md:text-5xl font-black text-slate-900">{t.periodic.title}</h2>
        <p className="text-slate-600 text-lg">{t.periodic.subtitle}</p>
      </div>

      <div className="relative max-w-md mx-auto">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
        <input 
          type="text" 
          placeholder="Pesquisar elemento..." 
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="w-full pl-12 pr-6 py-4 bg-white border border-slate-200 rounded-2xl shadow-sm focus:ring-2 focus:ring-blue-500 outline-none font-medium"
        />
      </div>

      <div className="overflow-x-auto pb-8">
        <div className="grid gap-1 min-w-[1000px] select-none" style={{ gridTemplateColumns: "repeat(18, minmax(0, 1fr))", gridAutoRows: "minmax(60px, auto)" }}>
          {elements.map((el) => {
            const isMatch = filteredElements.includes(el);
            const rowOffset = el.ypos >= 9 ? "mt-8" : "";
            
            return (
              <div 
                key={el.number}
                onClick={() => setSelected(el)}
                className={`
                  relative aspect-[4/5] p-1 flex flex-col justify-between rounded-lg border-2 cursor-pointer transition-all duration-200
                  ${categoryColors[el.category]}
                  ${isMatch ? "scale-100 opacity-100 hover:scale-110 hover:z-10 shadow-md" : "opacity-30 grayscale"}
                  ${rowOffset}
                `}
                style={{ gridColumn: el.xpos, gridRow: el.ypos }}
              >
                <span className="text-[10px] font-black opacity-60">{el.number}</span>
                <span className="text-xl font-black text-center">{el.symbol}</span>
                <span className="text-[8px] text-center truncate font-bold uppercase leading-tight">{el.name}</span>
              </div>
            );
          })}
        </div>
      </div>

      {/* Seção de Evolução Histórica */}
      <section className="max-w-4xl mx-auto space-y-8 bg-white p-8 md:p-12 rounded-[3rem] border border-slate-100 shadow-sm">
        <div className="flex items-center gap-4 mb-8">
          <div className="bg-blue-600 p-3 rounded-2xl text-white shadow-lg shadow-blue-100">
            <BookOpen className="w-6 h-6" />
          </div>
          <div>
            <h3 className="text-3xl font-black text-slate-900">{t.periodic.evolution}</h3>
            <div className="h-1 w-20 bg-blue-600 rounded-full mt-1"></div>
          </div>
        </div>

        <div className="prose prose-slate max-w-none">
          {t.periodic.evolutionFullText.split('\n\n').map((paragraph, i) => (
            <p key={i} className="text-slate-600 leading-relaxed text-lg font-medium mb-6">
              {paragraph}
            </p>
          ))}
        </div>
        
        <div className="pt-6 border-t border-slate-50 flex flex-wrap gap-4">
          <span className="px-4 py-2 bg-slate-100 rounded-full text-xs font-black text-slate-500 uppercase tracking-widest">Lavoisier</span>
          <span className="px-4 py-2 bg-slate-100 rounded-full text-xs font-black text-slate-500 uppercase tracking-widest">Döbereiner</span>
          <span className="px-4 py-2 bg-slate-100 rounded-full text-xs font-black text-slate-500 uppercase tracking-widest">Mendeleev</span>
          <span className="px-4 py-2 bg-slate-100 rounded-full text-xs font-black text-slate-500 uppercase tracking-widest">Moseley</span>
        </div>
      </section>

      {selected && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-lg overflow-hidden border border-slate-100 relative">
            <div className={`p-12 flex flex-col items-center text-center ${categoryColors[selected.category]} border-none relative`}>
              <button onClick={() => setSelected(null)} className="absolute top-6 right-6 p-2 bg-white/50 rounded-full hover:bg-white transition-colors">
                <X className="w-6 h-6 text-slate-800" />
              </button>
              <span className="text-8xl font-black mb-4 drop-shadow-sm">{selected.symbol}</span>
              <h3 className="text-3xl font-black">{selected.name}</h3>
              <span className="inline-block px-4 py-1 bg-white/40 rounded-full text-sm font-bold mt-4 uppercase tracking-widest">
                {t.periodic.categories[selected.category as keyof typeof t.periodic.categories] || selected.category}
              </span>
            </div>
            <div className="p-8 grid grid-cols-2 gap-4">
              <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                <span className="text-xs text-slate-500 font-black uppercase tracking-widest block mb-1">{t.periodic.atomicNumber}</span>
                <span className="text-3xl font-black text-slate-900">{selected.number}</span>
              </div>
              <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                <span className="text-xs text-slate-500 font-black uppercase tracking-widest block mb-1">{t.periodic.atomicMass}</span>
                <span className="text-3xl font-black text-slate-900">{selected.mass}</span>
              </div>
              <div className="col-span-2 p-6 bg-slate-50 rounded-3xl border border-slate-100 flex items-center gap-4">
                <div className="bg-blue-600 p-3 rounded-2xl text-white">
                  <Info className="w-6 h-6" />
                </div>
                <div className="overflow-hidden">
                  <span className="text-xs text-slate-500 font-black uppercase tracking-widest block mb-1">{t.periodic.config}</span>
                  <span className="font-mono font-bold text-slate-800 block truncate">{selected.electron_configuration}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PeriodicTable;
