
import React, { useState, useRef, useEffect } from 'react';
import { useLanguage } from '../context/LanguageContext';
import { GoogleGenAI } from "@google/genai";
import { Send, Bot, User, Sparkles, Loader2 } from 'lucide-react';

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

const AITutor: React.FC = () => {
  const { t } = useLanguage();
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', content: t.ai.intro }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    const newHistory: Message[] = [...messages, { role: 'user', content: userMessage }];
    setMessages(newHistory);
    setIsLoading(true);

    try {
      // Create a new GoogleGenAI instance right before the call as per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      
      // Map existing messages to the format expected by Gemini API (assistant -> model)
      const apiContents = newHistory.map(m => ({
        role: m.role === 'user' ? 'user' : 'model',
        parts: [{ text: m.content }]
      }));

      // Use gemini-3-pro-preview for complex STEM tasks like a Chemistry Tutor
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: apiContents,
        config: {
          systemInstruction: "Você é Thai, uma tutora de química especialista, amigável e didática. Explique conceitos de forma simples usando analogias do dia a dia. Se o usuário pedir cálculos, mostre o passo a passo detalhado.",
        }
      });

      // Use the .text property directly from the response object
      const aiResponse = response.text || "Desculpe, não consegui processar sua dúvida agora.";
      setMessages(prev => [...prev, { role: 'assistant', content: aiResponse }]);
    } catch (error) {
      console.error("Gemini API Error:", error);
      setMessages(prev => [...prev, { role: 'assistant', content: "Ocorreu um erro técnico ao processar sua dúvida. Por favor, tente novamente." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8 h-[calc(100vh-160px)] flex flex-col space-y-6">
      <div className="text-center">
        <h2 className="text-3xl font-black text-slate-900 flex items-center justify-center gap-3">
          <Sparkles className="text-amber-500" />
          {t.ai.title}
        </h2>
        <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{t.ai.subtitle}</p>
      </div>

      <div 
        ref={scrollRef}
        className="flex-grow bg-white rounded-3xl border border-slate-100 shadow-sm overflow-y-auto p-6 space-y-6 custom-scrollbar"
      >
        {messages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex gap-4 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className={`w-10 h-10 rounded-2xl flex items-center justify-center flex-shrink-0 ${
                msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-600'
              }`}>
                {msg.role === 'user' ? <User className="w-5 h-5" /> : <Bot className="w-5 h-5" />}
              </div>
              <div className={`p-5 rounded-3xl font-medium leading-relaxed whitespace-pre-wrap ${
                msg.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none' 
                  : 'bg-slate-50 text-slate-800 border border-slate-100 rounded-tl-none'
              }`}>
                {msg.content}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start animate-pulse">
            <div className="flex gap-4">
              <div className="w-10 h-10 rounded-2xl bg-slate-100 flex items-center justify-center">
                <Loader2 className="w-5 h-5 text-slate-400 animate-spin" />
              </div>
              <div className="bg-slate-50 h-12 w-24 rounded-3xl rounded-tl-none border border-slate-100"></div>
            </div>
          </div>
        )}
      </div>

      <div className="relative">
        <input 
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleSend()}
          placeholder={t.ai.placeholder}
          className="w-full pl-6 pr-16 py-5 bg-white border-2 border-slate-100 rounded-3xl shadow-xl focus:border-blue-500 outline-none transition-all font-medium text-lg"
        />
        <button 
          onClick={handleSend}
          disabled={isLoading}
          className="absolute right-3 top-1/2 -translate-y-1/2 p-3 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all disabled:opacity-50"
        >
          <Send className="w-6 h-6" />
        </button>
      </div>
    </div>
  );
};

export default AITutor;
