
import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, useLocation } from 'react-router-dom';
import { LanguageProvider } from './context/LanguageContext';
import Layout from './components/Layout';
import Home from './views/Home';
import AtomicModels from './views/AtomicModels';
import PeriodicTable from './views/PeriodicTable';
import Calculators from './views/Calculators';
import Redox from './views/Redox';
import AITutor from './views/AITutor';

const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const App: React.FC = () => {
  return (
    <LanguageProvider>
      <HashRouter>
        <ScrollToTop />
        <Routes>
          <Route path="/" element={<Layout />}>
            <Route index element={<Home />} />
            <Route path="modelos-atomicos" element={<AtomicModels />} />
            <Route path="tabela-periodica" element={<PeriodicTable />} />
            <Route path="calculadoras" element={<Calculators />} />
            <Route path="redox" element={<Redox />} />
            <Route path="ia-tutor" element={<AITutor />} />
          </Route>
        </Routes>
      </HashRouter>
    </LanguageProvider>
  );
};

export default App;
