
import React, { useState, useMemo } from 'react';
import { useLanguage } from '../context/LanguageContext';
import { 
  Calculator as CalcIcon, 
  RefreshCw, 
  Thermometer, 
  Gauge, 
  Box, 
  Weight, 
  Users, 
  FlaskConical, 
  Droplets,
  ArrowRightLeft
} from 'lucide-react';

type CalcType = 'mol' | 'molar_concentration' | 'mass_concentration' | 'avogadro';
type ConvType = 'temp' | 'pressure' | 'mass' | 'volume';

const Calculators: React.FC = () => {
  const { t } = useLanguage();
  const [activeTab, setActiveTab] = useState<'calc' | 'conv'>('calc');
  
  // States for Calculators
  const [activeCalc, setActiveCalc] = useState<CalcType>('mol');
  const [val1, setVal1] = useState('');
  const [val2, setVal2] = useState('');
  const [result, setResult] = useState<string | null>(null);

  // States for Converters
  const [activeConv, setActiveConv] = useState<ConvType | null>(null);
  const [convVal, setConvVal] = useState('');
  const [unitFrom, setUnitFrom] = useState('');
  const [unitTo, setUnitTo] = useState('');
  const [convResult, setConvResult] = useState<string | null>(null);

  const handleCalculate = () => {
    const v1 = parseFloat(val1);
    const v2 = parseFloat(val2);

    if (isNaN(v1)) return;

    switch (activeCalc) {
      case 'mol':
        if (!v2) return;
        setResult(`${(v1 / v2).toFixed(4)} mol`);
        break;
      case 'molar_concentration':
        if (!v2) return;
        setResult(`${(v1 / v2).toFixed(4)} mol/L`);
        break;
      case 'mass_concentration':
        if (!v2) return;
        setResult(`${(v1 / v2).toFixed(4)} g/L`);
        break;
      case 'avogadro':
        const NA = 6.02214076e23;
        const res = v1 * NA;
        setResult(res.toExponential(4) + " partículas");
        break;
    }
  };

  const handleConvert = () => {
    const v = parseFloat(convVal);
    if (isNaN(v) || !unitFrom || !unitTo) return;
    if (unitFrom === unitTo) {
      setConvResult(`${v} ${unitTo}`);
      return;
    }

    let res = 0;

    if (activeConv === 'temp') {
      let c = v;
      if (unitFrom === 'K') c = v - 273.15;
      if (unitFrom === 'F') c = (v - 32) * 5/9;

      if (unitTo === 'C') res = c;
      if (unitTo === 'K') res = c + 273.15;
      if (unitTo === 'F') res = (c * 9/5) + 32;
    } else if (activeConv === 'pressure') {
      let atm = v;
      if (unitFrom === 'mmHg') atm = v / 760;
      if (unitFrom === 'Pa') atm = v / 101325;
      if (unitFrom === 'bar') atm = v / 1.01325;

      if (unitTo === 'atm') res = atm;
      if (unitTo === 'mmHg') res = atm * 760;
      if (unitTo === 'Pa') res = atm * 101325;
      if (unitTo === 'bar') res = atm * 1.01325;
    } else if (activeConv === 'mass') {
      let g = v;
      if (unitFrom === 'kg') g = v * 1000;
      if (unitFrom === 'mg') g = v / 1000;

      if (unitTo === 'g') res = g;
      if (unitTo === 'kg') res = g / 1000;
      if (unitTo === 'mg') res = g * 1000;
    } else if (activeConv === 'volume') {
      let l = v;
      if (unitFrom === 'mL') l = v / 1000;
      if (unitFrom === 'm3') l = v * 1000;

      if (unitTo === 'L') res = l;
      if (unitTo === 'mL') res = l * 1000;
      if (unitTo === 'm3') res = l / 1000;
    }

    setConvResult(`${res.toFixed(4)} ${unitTo}`);
  };

  const units = useMemo(() => {
    switch (activeConv) {
      case 'temp': return ['C', 'K', 'F'];
      case 'pressure': return ['atm', 'mmHg', 'Pa', 'bar'];
      case 'mass': return ['kg', 'g', 'mg'];
      case 'volume': return ['L', 'mL', 'm3'];
      default: return [];
    }
  }, [activeConv]);

  const calcButtons = [
    { type: 'mol' as CalcType, label: t.calc.tools.mol, icon: <FlaskConical className="w-4 h-4" /> },
    { type: 'molar_concentration' as CalcType, label: t.calc.tools.concentration, icon: <Droplets className="w-4 h-4" /> },
    { type: 'mass_concentration' as CalcType, label: t.calc.tools.concentrationMass, icon: <Box className="w-4 h-4" /> },
    { type: 'avogadro' as CalcType, label: t.calc.tools.avogadro, icon: <Users className="w-4 h-4" /> },
  ];

  const convButtons = [
    { type: 'temp' as ConvType, label: t.calc.tools.temp, icon: <Thermometer className="w-4 h-4" /> },
    { type: 'pressure' as ConvType, label: t.calc.tools.pressure, icon: <Gauge className="w-4 h-4" /> },
    { type: 'mass' as ConvType, label: t.calc.tools.mass, icon: <Weight className="w-4 h-4" /> },
    { type: 'volume' as ConvType, label: t.calc.tools.volume, icon: <Box className="w-4 h-4" /> },
  ];

  const getInputLabels = () => {
    switch (activeCalc) {
      case 'mol': return { l1: t.calc.labels.mass, l2: t.calc.labels.molarMass };
      case 'molar_concentration': return { l1: t.calc.labels.mols, l2: t.calc.labels.volume };
      case 'mass_concentration': return { l1: t.calc.labels.mass, l2: t.calc.labels.volume };
      case 'avogadro': return { l1: t.calc.labels.mols, l2: t.calc.labels.avogadroConst };
      default: return { l1: 'Valor 1', l2: 'Valor 2' };
    }
  };

  const labels = getInputLabels();

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 space-y-8">
      {/* Tab Selector */}
      <div className="flex justify-center bg-white p-2 rounded-2xl shadow-sm border border-slate-100">
        <button 
          onClick={() => { setActiveTab('calc'); setActiveConv(null); setConvResult(null); }}
          className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'calc' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:bg-slate-50'}`}
        >
          {t.calc.tabs.calc}
        </button>
        <button 
          onClick={() => { setActiveTab('conv'); setResult(null); }}
          className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'conv' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-600 hover:bg-slate-50'}`}
        >
          {t.calc.tabs.conv}
        </button>
      </div>

      {activeTab === 'calc' ? (
        <>
          {/* Calculators Selector */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
            {calcButtons.map((btn) => (
              <button
                key={btn.type}
                onClick={() => {
                  setActiveCalc(btn.type);
                  setResult(null);
                  setVal1('');
                  setVal2('');
                }}
                className={`flex items-center gap-2 p-4 rounded-2xl border-2 font-bold text-sm transition-all ${
                  activeCalc === btn.type 
                    ? "bg-blue-50 border-blue-600 text-blue-700 shadow-sm" 
                    : "bg-white border-slate-100 text-slate-500 hover:border-slate-200"
                }`}
              >
                {btn.icon}
                {btn.label}
              </button>
            ))}
          </div>

          <div className="bg-white rounded-3xl p-8 border border-slate-100 shadow-sm space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-sm font-black text-slate-400 uppercase tracking-widest">{labels.l1}</label>
                <input 
                  type="number" 
                  value={val1} 
                  onChange={(e) => setVal1(e.target.value)}
                  className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none font-bold text-lg"
                  placeholder="0.00"
                />
              </div>
              {activeCalc !== 'avogadro' && (
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-400 uppercase tracking-widest">{labels.l2}</label>
                  <input 
                    type="number" 
                    value={val2} 
                    onChange={(e) => setVal2(e.target.value)}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none font-bold text-lg"
                    placeholder="0.00"
                  />
                </div>
              )}
              {activeCalc === 'avogadro' && (
                 <div className="space-y-2">
                    <label className="text-sm font-black text-slate-400 uppercase tracking-widest">{labels.l2}</label>
                    <div className="w-full px-6 py-4 bg-slate-100 border border-slate-200 rounded-2xl font-mono text-slate-500 flex items-center h-[62px]">
                       6.022 × 10²³
                    </div>
                 </div>
              )}
            </div>

            <button 
              onClick={handleCalculate}
              className="w-full py-5 bg-blue-600 text-white font-black text-xl rounded-2xl shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
            >
              {t.calc.btn}
            </button>

            {result && (
              <div className="p-8 bg-slate-900 text-white rounded-3xl text-center space-y-2 animate-in fade-in zoom-in duration-300">
                <span className="text-blue-400 text-xs uppercase font-black tracking-widest">{t.calc.result}</span>
                <div className="text-4xl font-black">{result}</div>
              </div>
            )}
          </div>
        </>
      ) : (
        <>
          {/* Converters Selector */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
            {convButtons.map((btn) => (
              <button
                key={btn.type}
                onClick={() => {
                  setActiveConv(btn.type);
                  setConvResult(null);
                  setConvVal('');
                  setUnitFrom('');
                  setUnitTo('');
                }}
                className={`flex items-center gap-2 p-4 rounded-2xl border-2 font-bold text-sm transition-all ${
                  activeConv === btn.type 
                    ? "bg-orange-50 border-orange-500 text-orange-700 shadow-sm" 
                    : "bg-white border-slate-100 text-slate-500 hover:border-slate-200"
                }`}
              >
                {btn.icon}
                {btn.label}
              </button>
            ))}
          </div>

          {activeConv ? (
            <div className="bg-white rounded-3xl p-8 border border-slate-100 shadow-sm space-y-8 animate-in fade-in slide-in-from-top-4 duration-300">
              <div className="space-y-4">
                <label className="text-sm font-black text-slate-400 uppercase tracking-widest">{t.calc.labels.value}</label>
                <input 
                  type="number" 
                  value={convVal} 
                  onChange={(e) => setConvVal(e.target.value)}
                  className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-orange-500 outline-none font-bold text-lg"
                  placeholder="0.00"
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-400 uppercase tracking-widest">{t.calc.labels.from}</label>
                  <select 
                    value={unitFrom} 
                    onChange={(e) => setUnitFrom(e.target.value)}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-orange-500 outline-none font-bold appearance-none cursor-pointer"
                  >
                    <option value="">--</option>
                    {units.map(u => <option key={u} value={u}>{u}</option>)}
                  </select>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-black text-slate-400 uppercase tracking-widest">{t.calc.labels.to}</label>
                  <select 
                    value={unitTo} 
                    onChange={(e) => setUnitTo(e.target.value)}
                    className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-orange-500 outline-none font-bold appearance-none cursor-pointer"
                  >
                    <option value="">--</option>
                    {units.map(u => <option key={u} value={u}>{u}</option>)}
                  </select>
                </div>
              </div>

              <button 
                onClick={handleConvert}
                className="w-full py-5 bg-orange-500 text-white font-black text-xl rounded-2xl shadow-xl shadow-orange-100 hover:bg-orange-600 transition-all active:scale-95"
              >
                {t.calc.btnConv}
              </button>

              {convResult && (
                <div className="p-8 bg-slate-900 text-white rounded-3xl text-center space-y-2 animate-in fade-in zoom-in duration-300">
                  <span className="text-orange-400 text-xs uppercase font-black tracking-widest">{t.calc.result}</span>
                  <div className="text-4xl font-black">{convResult}</div>
                </div>
              )}
            </div>
          ) : (
            <div className="bg-orange-50 p-12 rounded-3xl border border-dashed border-orange-200 text-center space-y-4">
              <div className="bg-white w-16 h-16 rounded-2xl flex items-center justify-center mx-auto shadow-sm text-orange-500">
                <ArrowRightLeft className="w-8 h-8" />
              </div>
              <p className="font-bold text-orange-800">Selecione um tipo de conversor acima para começar!</p>
            </div>
          )}
        </>
      )}
      
      <div className="flex items-center gap-2 p-4 bg-blue-50 border border-blue-100 rounded-2xl text-blue-800 text-sm font-medium">
         <CalcIcon className="w-4 h-4 flex-shrink-0" />
         Dica: Use pontos para casas decimais (Ex: 10.5)
      </div>
    </div>
  );
};

export default Calculators;
