
import React, { useState } from 'react';
import { useLanguage } from '../context/LanguageContext';
import { Zap, RefreshCw, AlertCircle, CheckCircle2 } from 'lucide-react';

const Redox: React.FC = () => {
  const { t } = useLanguage();
  const [noxInitial, setNoxInitial] = useState('');
  const [noxFinal, setNoxFinal] = useState('');
  const [result, setResult] = useState<{ type: 'ox' | 'red' | 'neutral', text: string } | null>(null);

  const checkRedox = () => {
    const ni = parseFloat(noxInitial);
    const nf = parseFloat(noxFinal);
    
    if (isNaN(ni) || isNaN(nf)) return;

    if (nf > ni) {
      setResult({ type: 'ox', text: t.redox.resOx });
    } else if (nf < ni) {
      setResult({ type: 'red', text: t.redox.resRed });
    } else {
      setResult({ type: 'neutral', text: t.redox.resNeutral });
    }
  };

  return (
    <div className="max-w-2xl mx-auto px-4 py-16 space-y-8">
      <div className="text-center space-y-4">
        <div className="inline-flex p-3 bg-red-100 rounded-2xl text-red-600 mb-2">
          <Zap className="w-8 h-8" />
        </div>
        <h2 className="text-4xl font-black text-slate-900">{t.redox.title}</h2>
        <p className="text-slate-600">{t.redox.subtitle}</p>
      </div>

      <div className="bg-white p-10 rounded-[2.5rem] border border-slate-100 shadow-xl space-y-8">
        <div className="grid grid-cols-2 gap-8">
          <div className="space-y-3">
            <label className="text-sm font-black text-slate-400 uppercase tracking-widest">{t.redox.inputInitial}</label>
            <input 
              type="number" 
              value={noxInitial}
              onChange={(e) => setNoxInitial(e.target.value)}
              className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-100 rounded-3xl text-2xl font-bold focus:border-blue-500 outline-none transition-all"
              placeholder="0"
            />
          </div>
          <div className="space-y-3">
            <label className="text-sm font-black text-slate-400 uppercase tracking-widest">{t.redox.inputFinal}</label>
            <input 
              type="number" 
              value={noxFinal}
              onChange={(e) => setNoxFinal(e.target.value)}
              className="w-full px-6 py-5 bg-slate-50 border-2 border-slate-100 rounded-3xl text-2xl font-bold focus:border-blue-500 outline-none transition-all"
              placeholder="+2"
            />
          </div>
        </div>

        <button 
          onClick={checkRedox}
          className="w-full py-5 bg-slate-900 text-white font-black text-xl rounded-3xl hover:bg-slate-800 transition-all active:scale-95 shadow-xl shadow-slate-200"
        >
          {t.redox.btnCheck}
        </button>

        {result && (
          <div className={`p-8 rounded-3xl border-2 flex items-start gap-4 animate-in fade-in slide-in-from-bottom-4 duration-500 ${
            result.type === 'ox' ? "bg-orange-50 border-orange-200 text-orange-900" :
            result.type === 'red' ? "bg-green-50 border-green-200 text-green-900" :
            "bg-slate-50 border-slate-200 text-slate-900"
          }`}>
            {result.type === 'neutral' ? <AlertCircle className="w-6 h-6 mt-1 flex-shrink-0" /> : <CheckCircle2 className="w-6 h-6 mt-1 flex-shrink-0" />}
            <p className="text-lg font-bold leading-tight">{result.text}</p>
          </div>
        )}
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="p-6 bg-orange-100 border border-orange-200 rounded-3xl space-y-2">
          <h4 className="font-black text-orange-900 uppercase tracking-wider">Oxidação</h4>
          <ul className="text-sm font-bold text-orange-800 space-y-1">
            <li>• Aumento do Nox</li>
            <li>• Perda de elétrons</li>
            <li>• Agente Redutor</li>
          </ul>
        </div>
        <div className="p-6 bg-green-100 border border-green-200 rounded-3xl space-y-2">
          <h4 className="font-black text-green-900 uppercase tracking-wider">Redução</h4>
          <ul className="text-sm font-bold text-green-800 space-y-1">
            <li>• Diminuição do Nox</li>
            <li>• Ganho de elétrons</li>
            <li>• Agente Oxidante</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default Redox;
